contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 arg) public payable {
        uint256 before = c.currentDifficulty(); if (__ESBMC_reverted()) return;

        uint256 after_;
        bool reverted = false;

        c.AdjustDifficulty(arg); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            after_ = c.currentDifficulty();
        } else {
            after_ = c.currentDifficulty();
        }

        assert(!reverted && after_ == arg || reverted && after_ == before);
    }
}

