// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 arg) internal {
        uint256 before;
        try c.currentDifficulty() returns (uint256 __r) { before = __r; } catch { return; }
        uint256 after_;
        bool reverted = false;
        try c.AdjustDifficulty(arg) {
            after_ = c.currentDifficulty();
        } catch {
            reverted = true;
            after_ = c.currentDifficulty();
        }
        assertTrue(!reverted && after_ == arg || reverted && after_ == before);
    }

    function testFuzz_run(uint256 arg) public {
        _run(arg);
    }

    receive() external payable {}
}
